@startuml

class Library {
}

class User {
  + securityDeposit : float
}

class BorrowableItem {
  + libraryCode : string
  + location : string
}

class Book {
  + publisher : string
}

class MagazineIssue {
  + publicationDate : date
  + publisher : string
}

class MusicCD {
  + publisher : string
  + artist : string
}

class Film {
  + duration : int
  + publisher : string
}

class VHSFilm extends Film {}

class DVDFilm extends Film {}

class MusicCDItem extends MusicCD {}

class BookItem extends Book {}

class MagazineIssueItem extends MagazineIssue {}

class Actor {}

class Author {}

class Loan {
  + returnDate : date
}

Library "1" -- "*" User : has
Library "1" -- "*" BorrowableItem : has
User "1" -- "0..3" Loan : borrows
Loan "1" -- "1" BorrowableItem : involves

BookItem "1" -- "1..*" Author : writtenBy
BookItem "1" -- "1" Actor : features
MagazineIssueItem "1" -- "1" Actor : features
MusicCDItem "1" -- "1" Actor : features
Film "1" -- "1..*" Actor : features

@enduml

